<?php $old=App\Core\Session::get('_old',[]);$value=static fn(string$key,mixed$default='')=>$old[$key]??($store[$key]??$default);$social=json_decode((string)($store['social_links']??''),true);if(!is_array($social))$social=[];$socialValue=static fn(string$key)=>$old[$key]??($social[$key]??'');$logo=$store['logo_path']??null;$banner=$store['banner_path']??null;$previewTheme=in_array($value('theme','modern'),$app['themes'],true)?$value('theme','modern'):'modern';$previewFont=isset($app['fonts'][$value('font_key','system')])?$value('font_key','system'):'system';$previewAccent=App\Support\Color::safeHex($value('accent_color','#2F5BFF')); ?>
